import "./App.css";
import { SheetComponent } from "@antv/s2-react";
import { data } from "./data";
import "@antv/s2-react/dist/style.min.css";

const options = {
  height: 600,
  width: 1250,
  showDefaultHeaderActionIcon: false,
  tooltip: {
    showTooltip: true,
    row: {
      showTooltip: true,
    },
  },
};

function buildData(rawData) {
  const table = rawData["table"];
  const data = [] // see data.js to see the expected format
  table["rows"].forEach((row) => {
    const r = {}
    row.forEach((col, colIndex) => {
      r[table["columns"][colIndex]] = col
    })
    data.push(r)
  })

  return {
    fields: {
      rows: rawData["rows"],
      columns: rawData["columns"],
      values: rawData["values"],
      valueInCols: true,
    },
    data
  }
}

function App() {
  const queryParameters = new URLSearchParams(window.location.search)
  const dataFromUrl = atob(queryParameters.get("data"));
  const finalData = dataFromUrl ? buildData(JSON.parse(dataFromUrl)) : data
  return (
    <div className="App">
      <SheetComponent dataCfg={finalData} options={options} />
    </div>
  );
}

export default App;
